import json
import os
import re
from typing import Any, Dict, Optional

from openai import OpenAI


def _find_json_block(text: str) -> str:
    if not text:
        raise ValueError("Empty model response")
    fenced = re.search(r"```(?:json)?\s*(.*?)```", text, re.DOTALL | re.IGNORECASE)
    if fenced:
        return fenced.group(1).strip()
    start = text.find("{")
    end = text.rfind("}")
    if start != -1 and end != -1 and end > start:
        return text[start : end + 1].strip()
    return text.strip()


def extract_structured_json(text: str, schema_hint: Optional[str] = None) -> Dict[str, Any]:
    """
    Calls a hosted OpenAI chat model to extract structured JSON from input text.

    Args:
        text: The raw text to parse.
        schema_hint: Optional JSON schema or natural-language hint describing the desired output.

    Returns:
        A Python dict parsed from the model's JSON output.
    """
    client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))
    if not client.api_key:
        raise EnvironmentError("OPENAI_API_KEY is not set")

    model = os.getenv("OPENAI_MODEL", "gpt-4o-mini")

    prompt = (
        "Extract the requested structured information from the text and return ONLY valid JSON.\n"
        "Do not include markdown, commentary, or extra keys unless supported by the text.\n"
    )
    if schema_hint:
        prompt += f"\nSchema / instructions:\n{schema_hint}\n"
    prompt += f"\nText:\n{text}\n"

    response = client.chat.completions.create(
        model=model,
        messages=[
            {"role": "system", "content": "You are a precise information extraction engine."},
            {"role": "user", "content": prompt},
        ],
        temperature=0,
    )

    content = response.choices[0].message.content or ""
    json_text = _find_json_block(content)
    return json.loads(json_text)
